import { Model } from "pinia-orm";
import { Attr, Num, Str, Uid, Cast, BelongsTo } from "pinia-orm/decorators";
import { DateCast } from "pinia-orm/casts";
import type { TicketMetrics } from "@/types";
import { useSharedTimestamp } from "@/shared";
import TicketCategory from "./TicketCategory";
import Operator from "./Operator";

export default class Ticket extends Model {
    static entity = "tickets";

    static primaryKey = "uuid";

    @Uid() uuid!: string;
    @Str("") category_uuid!: string;
    @Str(null) handler_uuid!: string | null;
    @Attr() meta!: Record<string, string> | null;
    @Attr() metrics!: Record<string, TicketMetrics> | null;
    @Num(0) initial_weight!: number;
    @Num(0) weight_increment!: number;
    @Num(0) complexity!: number;
    @Num(0) delay!: number;
    @Num(0) reservation!: number;
    @Cast(() => DateCast) @Attr() created_at!: Date;
    @Cast(() => DateCast) @Attr(null) bound_at!: Date | null;
    @Cast(() => DateCast) @Attr(null) accepted_at!: Date | null;

    @BelongsTo(() => TicketCategory, "category_uuid") category!: TicketCategory;

    @BelongsTo(() => Operator, "handler_uuid") handler!: Operator | null;

    get duration() {
        return Math.round((useSharedTimestamp().value - this.created_at.getTime()) / 1000);
    }

    get weight() {
        return this.initial_weight + this.weight_increment * this.duration;
    }
}
